import pyatspi
app = [a for a in pyatspi.Registry.getDesktop(0) if a.name=='soffice'][0]
def states(o):
    try: return ','.join([pyatspi.stateToString(s) for s in o.getState().getStates()])
    except: return ''
def walk(o,d=0):
    if d>8: return
    try: name=o.name; role=o.getRoleName(); desc=o.description
    except Exception as e: return
    print('  '*d + f'{role} name={name"'!r} desc={desc!r} children={o.childCount} states={states(o)}'"')
    for i in range(o.childCount):
        walk(o[i], d+1)
for i in range(app.childCount):
    if app[i].getRoleName()=='dialog':
        walk(app[i])
