/bin/bash -lc "DISPLAY=:0 python3 - <<'PY'
import pyatspi, time
app=[a for a in pyatspi.Registry.getDesktop(0) if a.name=='soffice'][0]
dialog=[app[i] for i in range(app.childCount) if app[i].getRoleName()=='dialog'][0]
spins=[]; buttons=[]
def walk(o):
    if o.getRoleName()=='spin button': spins.append(o)
    if o.getRoleName()=='push button': buttons.append(o)
    for i in range(o.childCount): walk(o[i])
walk(dialog)
for idx,s in enumerate(spins):
    print(idx, s.description)
    for q in ['queryValue','queryText','queryAction','queryComponent']:
        try:
            obj=getattr(s,q)(); print(' ',q,'ok', type(obj))
            if q=='queryValue': print('  val', obj.currentValue, obj.minimumValue, obj.maximumValue)
            if q=='queryText': print('  text', obj.getText(0,-1))
        except Exception as e: print(' ',q,'no',type(e).__name__, e)
print('buttons',[b.name for b in buttons])
