import pyatspi
app=[a for a in pyatspi.Registry.getDesktop(0) if a.name=='soffice'][0]
print('children', [(app[i].getRoleName(), app[i].name) for i in range(app.childCount)])
# Count table roles in writer frame, shallow/deep with limit
count=0
def walk(o,d=0):
    global count
    try: role=o.getRoleName(); name=o.name
    except: return
    if role in ('table','table cell'):
        count += 1
        if count<20: print(role, repr(name), 'children', o.childCount)
    if d<12:
        for i in range(min(o.childCount,200)):
            walk(o[i],d+1)
for i in range(app.childCount):
    if app[i].getRoleName()=='frame': walk(app[i])
print('table role count', count)
PY"

